#[cfg(test)]
mod tests {
    use super::*;

    /// The `{0}`, `{1}`... markers a string contains, sorted.
    fn markers(s: &str) -> Vec<String> {
        let mut v: Vec<String> = s
            .match_indices('{')
            .filter_map(|(i, _)| {
                let rest = &s[i..];
                rest.find('}').map(|j| rest[..=j].to_string())
            })
            .collect();
        v.sort();
        v
    }

    #[test]
    fn every_message_has_text_in_every_language() {
        for &m in Msg::ALL {
            for lang in Language::ALL {
                assert!(!t(lang, m).trim().is_empty(), "{m:?} is empty in {lang:?}");
            }
        }
    }

    #[test]
    fn every_translation_keeps_the_same_placeholders_as_english() {
        for &m in Msg::ALL {
            let english = markers(t(Language::English, m));
            for lang in Language::ALL {
                assert_eq!(
                    markers(t(lang, m)),
                    english,
                    "{m:?} has different placeholders in {lang:?}"
                );
            }
        }
    }

    #[test]
    fn placeholders_are_filled_in() {
        assert_eq!(
            trf(Language::English, Msg::LocksInSecs, &[&5]),
            "Locks in 5 s"
        );
        assert_eq!(trf(Language::Urdu, Msg::DaysAgo, &[&3]), "3 دن پہلے");
    }

    #[test]
    fn scripts_match_the_language() {
        let in_range =
            |s: &str, lo: u32, hi: u32| s.chars().any(|c| (lo..=hi).contains(&(c as u32)));
        let ranges = [
            (Language::Hindi, 0x900, 0x97F),
            (Language::Sanskrit, 0x900, 0x97F),
            (Language::Tamil, 0xB80, 0xBFF),
            (Language::Telugu, 0xC00, 0xC7F),
            (Language::Malayalam, 0xD00, 0xD7F),
            (Language::Urdu, 0x600, 0x6FF),
        ];
        for (lang, lo, hi) in ranges {
            assert!(
                in_range(t(lang, Msg::WelcomeTitle), lo, hi),
                "{lang:?} welcome text is in the wrong script"
            );
        }
    }
}
